import { test } from "node:test";
import assert from "node:assert/strict";

import {
  GaussKrugerProjection,
  type GaussKrugerProjectionOptions,
  type MGA2020Zone,
  projectMGA2020,
  inverseMGA2020,
  mga2020ZoneFromLongitude,
  mga2020CentralMeridian,
  createMGA2020,
} from "../dist/index.js";

const assertNear = (actual: number, expected: number, tolerance: number) => {
  assert.ok(
    Math.abs(actual - expected) <= tolerance,
    `Expected ${actual} to be within ${tolerance} of ${expected}`,
  );
};

// Independent fixtures generated by PROJ 9.8.1, not this implementation.
// MGA2020: +proj=tmerc +ellps=GRS80 +lon_0=153 +lat_0=0
//          +k=0.9996 +x_0=500000 +y_0=10000000 (EPSG:7856).
// Projection definition: https://epsg.io/7856
const sydney = {
  latitude: -33.8688,
  longitude: 151.2093,
  easting: 334368.6336472522,
  northing: 6250948.345488558,
};

const greenwichOptions = {
  centralMeridian: 0,
  scale: 1,
  falseEasting: 0,
  falseNorthing: 0,
};

// +proj=tmerc +ellps=WGS84 +lon_0=0 +lat_0=0 +k=1 +x_0=0 +y_0=0
const wgs84Fixtures = [
  { latitude: 0, longitude: 40, easting: 4869525.747989006, northing: 0 },
  {
    latitude: 51.4778,
    longitude: 2,
    easting: 138942.1934937768,
    northing: 5707139.914732401,
  },
  {
    latitude: 89.999999,
    longitude: 0,
    easting: 0,
    northing: 10001965.617618743,
  },
  {
    latitude: -89.999999,
    longitude: 0,
    easting: 0,
    northing: -10001965.617618743,
  },
  { latitude: 90, longitude: 0, easting: 0, northing: 10001965.729312722 },
  { latitude: -90, longitude: 0, easting: 0, northing: -10001965.729312722 },
];

test("MGA2020 forward matches an independent Sydney reference within 10 micrometers", () => {
  const grid = projectMGA2020(sydney.latitude, sydney.longitude);
  assert.equal(grid.zone, 56);
  assertNear(grid.easting, sydney.easting, 1e-5);
  assertNear(grid.northing, sydney.northing, 1e-5);
});

test("MGA2020 inverse consumes independent reference coordinates", () => {
  const geographic = inverseMGA2020(56, sydney.easting, sydney.northing);
  assertNear(geographic.latitude, sydney.latitude, 1e-10);
  assertNear(geographic.longitude, sydney.longitude, 1e-10);
});

test("WGS84 forward matches independent references, including 40 degrees off meridian", () => {
  const projection = new GaussKrugerProjection(greenwichOptions);
  for (const fixture of wgs84Fixtures) {
    const grid = projection.geodeticToGrid(fixture.latitude, fixture.longitude);
    // Fourth-order truncation is largest at the 40-degree equatorial fixture.
    assertNear(grid.easting, fixture.easting, 3e-5);
    assertNear(grid.northing, fixture.northing, 3e-5);
  }
});

test("WGS84 inverse matches independent ordinary and near-pole references", () => {
  const projection = new GaussKrugerProjection(greenwichOptions);
  for (const fixture of wgs84Fixtures.slice(1)) {
    const geographic = projection.gridToGeodetic(fixture.northing, fixture.easting);
    assertNear(geographic.latitude, fixture.latitude, 1e-11);
    // Longitude at an exact pole is undefined.
    if (Math.abs(fixture.latitude) < 90) {
      assertNear(geographic.longitude, fixture.longitude, 1e-10);
    }
  }
});

test("near-pole round trips retain latitude precision rather than clipping asin", () => {
  const projection = new GaussKrugerProjection({ centralMeridian: 153 });
  for (const latitude of [-89.9, -89.999999, -89.99999999, 89.9, 89.999999, 89.99999999]) {
    for (const longitude of [150, 153, 156]) {
      const grid = projection.geodeticToGrid(latitude, longitude);
      const geographic = projection.gridToGeodetic(grid.northing, grid.easting);
      assertNear(geographic.latitude, latitude, 1e-12);
    }
  }
});

test("exact poles have false easting and invert to the central-meridian convention", () => {
  for (const latitudeOfOrigin of [-90, -40, 0, 40, 90]) {
    const projection = new GaussKrugerProjection({
      centralMeridian: 153,
      latitudeOfOrigin,
      falseNorthing: 10000000,
    });
    for (const latitude of [-90, 90]) {
      const grid = projection.geodeticToGrid(latitude, -27);
      assert.equal(grid.easting, projection.falseEasting);
      const geographic = projection.gridToGeodetic(grid.northing, grid.easting);
      assertNear(geographic.latitude, latitude, 1e-12);
      assert.equal(geographic.longitude, 153);
    }
  }
});

test("nonzero latitude of origin matches independent forward and inverse references", () => {
  // PROJ 9.8.1: +proj=tmerc +ellps=WGS84 +lon_0=-75 +lat_0=40
  //             +k=0.9999 +x_0=600000 +y_0=200000
  const projection = new GaussKrugerProjection({
    centralMeridian: -75,
    latitudeOfOrigin: 40,
    scale: 0.9999,
    falseEasting: 600000,
    falseNorthing: 200000,
  });
  const grid = projection.geodeticToGrid(41.25, -73.5);
  assertNear(grid.easting, 725714.049570067, 1e-5);
  assertNear(grid.northing, 339879.609198174, 1e-5);
  const geographic = projection.gridToGeodetic(339879.609198174, 725714.049570067);
  assertNear(geographic.latitude, 41.25, 1e-10);
  assertNear(geographic.longitude, -73.5, 1e-10);
  const origin = projection.geodeticToGrid(40, -75);
  assert.equal(origin.easting, 600000);
  assertNear(origin.northing, 200000, 1e-8);
});

test("wrapped longitudes produce equivalent grids across the actual dateline", () => {
  for (const centralMeridian of [-177, 177, 537]) {
    const projection = new GaussKrugerProjection({ centralMeridian });
    const grid = projection.geodeticToGrid(-20, -179.9);
    for (const longitude of [180.1, 540.1, -539.9]) {
      const wrapped = projection.geodeticToGrid(-20, longitude);
      assertNear(wrapped.easting, grid.easting, 1e-7);
      assertNear(wrapped.northing, grid.northing, 1e-7);
    }
    const geographic = projection.gridToGeodetic(grid.northing, grid.easting);
    assertNear(geographic.latitude, -20, 1e-10);
    assertNear(geographic.longitude, centralMeridian === -177 ? -179.9 : centralMeridian === 177 ? 180.1 : 540.1, 1e-10);
  }
});

test("MGA2020 zoning uses six-degree boundaries and preserves mainland clamping", () => {
  for (let zone = 49; zone <= 56; zone++) {
    const meridian = zone * 6 - 183;
    assert.equal(mga2020CentralMeridian(zone), meridian);
    assert.equal(mga2020ZoneFromLongitude(meridian), zone);
    if (zone > 49) {
      const boundary = meridian - 3;
      assert.equal(mga2020ZoneFromLongitude(boundary - 1e-9), zone - 1);
      assert.equal(mga2020ZoneFromLongitude(boundary), zone);
      assert.equal(mga2020ZoneFromLongitude(boundary + 1e-9), zone);
    }
  }
  for (const longitude of [-Number.MAX_VALUE, -180, 0, 107.999999]) {
    assert.equal(mga2020ZoneFromLongitude(longitude), 49);
  }
  for (const longitude of [156, 180, 360, Number.MAX_VALUE]) {
    assert.equal(mga2020ZoneFromLongitude(longitude), 56);
  }
});

test("all projection numeric options reject nonfinite values", () => {
  const keys: (keyof GaussKrugerProjectionOptions)[] = [
    "equatorialRadius", "flattening", "centralMeridian", "latitudeOfOrigin",
    "scale", "falseEasting", "falseNorthing",
  ];
  for (const key of keys) {
    for (const value of [NaN, Infinity, -Infinity]) {
      assert.throws(
        () => new GaussKrugerProjection({ [key]: value }),
        new RegExp(`${key} must be a finite number`),
      );
    }
  }
});

test("projection parameter ranges reject invalid radius, flattening, scale and origin", () => {
  for (const equatorialRadius of [-1, 0]) {
    assert.throws(() => new GaussKrugerProjection({ equatorialRadius }), /equatorialRadius must be > 0/);
  }
  for (const flattening of [-1, 0, 0.01, 0.1]) {
    assert.throws(() => new GaussKrugerProjection({ flattening }), /flattening must be in \(0, 0.01\)/);
  }
  for (const scale of [-1, 0, 2, 3]) {
    assert.throws(() => new GaussKrugerProjection({ scale }), /scale must be in \(0, 2\)/);
  }
  for (const latitudeOfOrigin of [-90.000001, 90.000001]) {
    assert.throws(() => new GaussKrugerProjection({ latitudeOfOrigin }), /latitudeOfOrigin must be in \[-90, 90\]/);
  }
});

test("geographic and grid inputs reject nonfinite values and out-of-range latitude", () => {
  const projection = new GaussKrugerProjection();
  for (const value of [NaN, Infinity, -Infinity]) {
    assert.throws(() => projection.geodeticToGrid(value, 153), /latitude\/longitude must be finite numbers/);
    assert.throws(() => projection.geodeticToGrid(0, value), /latitude\/longitude must be finite numbers/);
    assert.throws(() => projection.gridToGeodetic(value, 500000), /northing\/easting must be finite numbers/);
    assert.throws(() => projection.gridToGeodetic(0, value), /northing\/easting must be finite numbers/);
    assert.throws(() => mga2020ZoneFromLongitude(value), /longitude must be a finite number/);
    assert.throws(() => projectMGA2020(-33, value), /longitude must be a finite number/);
  }
  for (const latitude of [-91, -90.000001, 90.000001, 91]) {
    assert.throws(() => projection.geodeticToGrid(latitude, 153), /latitude must be in \[-90, 90\]/);
    assert.throws(() => projectMGA2020(latitude, 153), /latitude must be in \[-90, 90\]/);
  }
});

test("MGA2020 helpers validate zones at runtime for JavaScript callers", () => {
  for (const zone of [NaN, Infinity, -Infinity, 0, 48, 57, 60, 49.5, "56", null, undefined]) {
    const runtimeZone = zone as unknown as MGA2020Zone;
    assert.throws(() => mga2020CentralMeridian(runtimeZone), /MGA2020 zone must be an integer in \[49, 56\]/);
    assert.throws(() => createMGA2020(runtimeZone), /MGA2020 zone must be an integer in \[49, 56\]/);
    assert.throws(() => inverseMGA2020(runtimeZone, 500000, 10000000), /MGA2020 zone must be an integer in \[49, 56\]/);
  }
});
